    find "$LOG_DIR" -name '*.log' -mtime "-$days" -exec grep -h -e "$pattern" -- {} +
}

main() {
    [[ $# -ge 1 ]] || usage
    local pattern="$1"
    local days="${2:-7}"
    local sort_opt="${3:-}"
    [[ "$days" =~ ^[0-9]+$ ]] || usage
    echo "executando busca em $LOG_DIR" >&2
    case "$sort_opt" in
        "") search_logs "$pattern" "$days" | head -n 200 ;;
        -r|-n|-u) search_logs "$pattern" "$days" | sort "$sort_opt" | head -n 200 ;;
        *) usage ;;
    esac
}

main "$@"

